// ===== 12. match =====

#[test]
fn non_exhaustive_match_rejected() {
    let src = "enum Shape:\n    Circle(int)\n    Square(int)\n\
               fn area(s: Shape) -> int:\n    match s:\n        Shape.Circle(r): return r\n";
    rejects(src, "non-exhaustive match on Shape: missing Square");
}

