fn neg_literal_arm_non_exhaustive_without_wildcard() {
    // A negative literal arm does NOT close the int domain — `_` is still required.
    rejects(
        "n := -3\nmatch n:\n    -3: print(\"a\")\n    -5: print(\"b\")\n",
        "non-exhaustive",
    );
}

